function showSaleInvoice(saleId){Promise.all([data(),getBusinessProfile()]).then(([d,p])=>{const selected=d.sales.find(x=>x.id===saleId);if(!selected)return;const invoice=selected.invoiceNo||("INV-"+String(selected.id).slice(-8).toUpperCase()),group=d.sales.filter(x=>(x.invoiceNo||x.id)===(selected.invoiceNo||selected.id));const customer=d.customers.find(x=>x.id===selected.customerId),returns=d.sales_returns.filter(x=>group.some(s=>s.id===x.saleId)),returned=sum(returns,x=>Number(x.amount||0)),received=sum(group,x=>Number(x.paid||0))-sum(returns,x=>Number(x.refundPaid||0)),total=sum(group,x=>Number(x.total||0)),subtotal=sum(group,x=>Number(x.grossTotal??x.total)),discount=sum(group,x=>Number(x.discountShare||0)),balance=total-returned-received;const logo=p.logoUrl&&/^https:\/\//i.test(p.logoUrl)?'<img class="invoice-logo" src="'+escapeHTML(p.logoUrl)+'" alt="Business logo">':"";const contact=[p.phone,p.email,p.address].filter(Boolean).map(escapeHTML).join(" · ");const itemRows=group.map(s=>[escapeHTML(s.productName),String(s.qty)+" "+escapeHTML(s.unit||""),money(s.grossRate??s.rate),money(s.grossTotal??s.total)]);modal("Sales invoice",'<div class="invoice-paper"><div class="invoice-brand"><div class="invoice-business">'+logo+'<div><h2>'+escapeHTML(p.name||"Karobaar Manager")+'</h2>'+(contact?'<p>'+contact+'</p>':'')+'<p>Sales invoice</p></div></div><div class="invoice-number"><b>'+escapeHTML(invoice)+'</b><small>'+fmtDate(selected.date)+'</small></div></div><div class="invoice-customer"><small>BILL TO</small><b>'+escapeHTML(selected.customerName||"Walk-in customer")+'</b>'+(customer?.phone?'<span>'+escapeHTML(customer.phone)+'</span>':'')+'</div>'+table(["ITEM","QTY","RATE","AMOUNT"],itemRows)+'<div class="invoice-totals"><div><span>Subtotal</span><b>'+money(subtotal)+'</b></div><div><span>Discount</span><b>-'+money(discount)+'</b></div><div><span>Returns / credits</span><b>'+money(returned)+'</b></div><div><span>Amount received</span><b class="positive">'+money(received)+'</b></div><div class="invoice-balance"><span>'+(balance<0?"Customer credit":"Balance due")+'</span><b>'+money(Math.abs(balance))+'</b></div></div><p class="invoice-thanks">'+escapeHTML(p.invoiceFooter||"Thank you for your business.")+'</p></div><div class="form-actions invoice-actions"><button class="button" id="printInvoice">Print / Save PDF</button></div>');$("#printInvoice").onclick=()=>window.print();});}
function customerBalance(d,c){const sales=d.sales.filter(x=>x.customerId===c.id),returns=d.sales_returns.filter(x=>x.customerId===c.id);const total=sum(sales,x=>Number(x.total||0))-sum(returns,x=>Number(x.amount||0));const paid=sum(sales,x=>Number(x.paid||0))+sum(d.payments.filter(x=>x.customerId===c.id),x=>Number(x.amount||0))-sum(returns,x=>Number(x.refundPaid||0));return {sales,total,paid,balance:total-paid};}
function customersPage(d){return pageIntro("Customers","Open a customer to see purchases and payments.","customer","Add customer")+(d.customers.length?'<div class="table-panel">'+table(["CUSTOMER","PHONE","SALES","TOTAL PURCHASES","RECEIVED","BALANCE",""],d.customers.map(c=>{const b=customerBalance(d,c);return ['<b>'+escapeHTML(c.name)+'</b>',escapeHTML(c.phone||"—"),b.sales.length,money(b.total),money(b.paid),'<span class="'+(b.balance>0?"negative":"positive")+'">'+money(b.balance)+'</span>','<button class="button secondary small" data-action="ledger" data-customer-id="'+c.id+'">View ledger</button>'];}))+'</div>':'<div class="panel empty"><b>No customers yet</b>Save a customer once, then select them quickly whenever they buy.</div>');}
function showCustomerLedger(customerId){data().then(d=>{const c=d.customers.find(x=>x.id===customerId);if(!c)return;const b=customerBalance(d,c);const rows=groupSalesByInvoice(b.sales).map(g=>[fmtDate(g.date),"Sale · "+g.invoiceNo,escapeHTML(g.items.map(x=>x.productName+" × "+x.qty+" "+(x.unit||"")).join(", ")),money(g.total),money(g.paid)]);d.payments.filter(x=>x.customerId===c.id).forEach(x=>rows.push([fmtDate(x.date),"Payment received",escapeHTML(x.note||"Customer payment"),"—",money(x.amount)]));d.sales_returns.filter(x=>x.customerId===c.id).forEach(x=>rows.push([fmtDate(x.date),"Sales return",escapeHTML(x.productName)+" · "+x.qty+" "+escapeHTML(x.unit||""),"-"+money(x.amount),money(x.refundPaid||0)]));rows.sort((a,z)=>a[0].localeCompare(z[0]));modal(escapeHTML(c.name),'<div class="statement-heading"><h2>Karobaar Manager</h2><p>Customer account statement</p><b>'+escapeHTML(c.name)+'</b><small>Generated: '+fmtDate(today())+'</small></div><div class="report-cards"><div class="report-card"><span>Total purchases</span><b>'+money(b.total)+'</b></div><div class="report-card"><span>Received</span><b class="positive">'+money(b.paid)+'</b></div><div class="report-card"><span>Outstanding</span><b class="'+(b.balance>0?"negative":"positive")+'">'+money(b.balance)+'</b></div></div><div class="panel-head" style="margin-top:18px"><h3>Customer ledger</h3><div class="statement-actions"><button class="button secondary small" id="printStatement">Print / Save PDF</button><button class="button small" data-action="payment" data-customer-id="'+c.id+'" '+(b.balance<=0?"disabled":"")+'>＋ Receive payment</button></div></div>'+(rows.length?table(["DATE","TYPE","DETAIL","SALE","RECEIVED"],rows):'<div class="empty">No transactions yet.</div>'));$("#printStatement").onclick=()=>window.print();});}
function stockAdjustmentsPage(d){const rows=[...d.stock_adjustments].sort((a,b)=>b.createdAt-a.createdAt);return pageIntro("Stock adjustments","Record damaged, missing, found or corrected stock.","stock-adjustment","Adjust stock")+(rows.length?'<div class="table-panel">'+table(["DATE","PRODUCT","CHANGE","REASON","STOCK LOSS VALUE"],rows.map(x=>[fmtDate(x.date),escapeHTML(x.productName),(x.delta>0?"+":"")+x.delta+" "+escapeHTML(x.unit||""),escapeHTML(x.reason),x.lossValue?money(x.lossValue):"—"]))+'</div>':'<div class="panel empty"><b>No stock adjustments</b>Record a stock correction when actual stock differs from the app.</div>')+'<div class="panel stock-note"><b>Accounting note</b><p>Stock reductions are counted as stock loss in net profit. Stock increases correct inventory quantity but are not treated as purchases or cash investment.</p></div>';}
function salesReturnsPage(d){const rows=[...d.sales_returns].sort((a,b)=>b.createdAt-a.createdAt);return pageIntro("Sales returns","Review returned goods, customer credits and refunds.")+(rows.length?'<div class="table-panel">'+table(["DATE","INVOICE","CUSTOMER","PRODUCT","QTY","RETURN VALUE","CASH REFUNDED","STOCK"],rows.map(x=>[fmtDate(x.date),escapeHTML(x.invoiceNo||"—"),escapeHTML(x.customerName),escapeHTML(x.productName),x.qty+" "+escapeHTML(x.unit||""),money(x.amount),money(x.refundPaid||0),x.restocked?"Restocked":"Not restocked"]))+'</div>':'<div class="panel empty"><b>No sales returns</b>Open Sales History and select Return on an invoice.</div>');}
function batchAllocations(d,productId,qty){let remaining=qty;const batches=d.inventory_batches.filter(x=>x.productId===productId&&Number(x.remaining||0)>0).sort((a,b)=>(a.expiryDate||"9999-12-31").localeCompare(b.expiryDate||"9999-12-31")||Number(a.createdAt||0)-Number(b.createdAt||0));const allocations=[];for(const batch of batches){if(remaining<=0)break;const take=Math.min(remaining,Number(batch.remaining));batch.remaining-=take;allocations.push({batchId:batch.id,qty:take});remaining-=take;}return allocations;}
async function showProductHistory(productId){const d=await data(),p=d.products.find(x=>x.id===productId);if(!p)return;const rows=[];d.purchases.filter(x=>x.productId===productId).forEach(x=>rows.push([fmtDate(x.date),"Purchase",x.batchNo||"—",x.qty+" "+(x.unit||""),money(x.total)]));d.sales.filter(x=>x.productId===productId).forEach(x=>rows.push([fmtDate(x.date),"Sale",x.invoiceNo||"—","-"+x.qty+" "+(x.unit||""),money(x.total)]));d.stock_adjustments.filter(x=>x.productId===productId).forEach(x=>rows.push([fmtDate(x.date),"Stock adjustment",x.reason,(x.delta>0?"+":"")+x.delta+" "+(x.unit||""),money(x.lossValue||0)]));d.sales_returns.filter(x=>x.productId===productId).forEach(x=>rows.push([fmtDate(x.date),"Sales return",x.reason,(x.restocked?"+":"")+x.qty+" "+(x.unit||""),money(x.amount)]));rows.sort((a,b)=>a[0].localeCompare(b[0]));const batches=d.inventory_batches.filter(x=>x.productId===productId).sort((a,b)=>(a.expiryDate||"9999").localeCompare(b.expiryDate||"9999"));modal(escapeHTML(p.name),'<h3>Transaction history</h3>'+(rows.length?table(["DATE","TYPE","REFERENCE / REASON","QUANTITY","VALUE"],rows):'<div class="empty">No transactions recorded.</div>')+'<h3 style="margin-top:20px">Stock batches</h3>'+(batches.length?table(["BATCH","EXPIRY","REMAINING"],batches.map(x=>[escapeHTML(x.batchNo||"—"),fmtDate(x.expiryDate),Number(x.remaining||0)+" "+escapeHTML(p.unit||"")])):'<div class="empty">No batch records.</div>'));}
function supplierBalance(d,s){const purchases=d.purchases.filter(x=>x.supplierId===s.id);const total=sum(purchases,x=>Number(x.total||0));const paid=sum(d.supplier_payments.filter(x=>x.supplierId===s.id),x=>Number(x.amount||0));return {purchases,total,paid,balance:total-paid};}
function suppliersPage(d){return pageIntro("Suppliers","Manage suppliers, purchase balances and payments.","supplier","Add supplier")+(d.suppliers.length?'<div class="table-panel">'+table(["SUPPLIER","PHONE","PURCHASES","TOTAL PURCHASES","PAID","PAYABLE",""],d.suppliers.map(s=>{const b=supplierBalance(d,s);return ['<b>'+escapeHTML(s.name)+'</b>',escapeHTML(s.phone||"—"),b.purchases.length,money(b.total),money(b.paid),'<span class="'+(b.balance>0?"negative":"positive")+'">'+money(b.balance)+'</span>','<button class="button secondary small" data-action="supplier-ledger" data-supplier-id="'+s.id+'">View ledger</button>'];}))+'</div>':'<div class="panel empty"><b>No suppliers added</b>Add your regular suppliers to track purchases and outstanding payments.</div>');}
function showSupplierLedger(supplierId){data().then(d=>{const s=d.suppliers.find(x=>x.id===supplierId);if(!s)return;const b=supplierBalance(d,s);const rows=b.purchases.map(x=>[fmtDate(x.date),"Purchase",escapeHTML(x.productName)+" · "+x.qty+" "+escapeHTML(x.unit||""),money(x.total),"—"]);d.supplier_payments.filter(x=>x.supplierId===s.id).forEach(x=>rows.push([fmtDate(x.date),"Payment made",escapeHTML(x.note||"Supplier payment"),"—",money(x.amount)]));rows.sort((a,z)=>a[0].localeCompare(z[0]));modal(escapeHTML(s.name),'<div class="statement-heading"><h2>Karobaar Manager</h2><p>Supplier account statement</p><b>'+escapeHTML(s.name)+'</b><small>Generated: '+fmtDate(today())+'</small></div><div class="report-cards"><div class="report-card"><span>Total purchases</span><b>'+money(b.total)+'</b></div><div class="report-card"><span>Paid</span><b class="positive">'+money(b.paid)+'</b></div><div class="report-card"><span>Payable</span><b class="'+(b.balance>0?"negative":"positive")+'">'+money(b.balance)+'</b></div></div><div class="panel-head" style="margin-top:18px"><h3>Supplier ledger</h3><div class="statement-actions"><button class="button secondary small" id="printSupplierStatement">Print / Save PDF</button><button class="button small" data-action="supplier-payment" data-supplier-id="'+s.id+'" '+(b.balance<=0?"disabled":"")+'>＋ Record payment</button></div></div>'+(rows.length?table(["DATE","TYPE","DETAIL","PURCHASE","PAID"],rows):'<div class="empty">No transactions yet.</div>'));$("#printSupplierStatement").onclick=()=>window.print();});}
function purchasesPage(d){const rows=[...d.purchases].sort((a,b)=>b.createdAt-a.createdAt);return pageIntro("Purchases & stock-in","Record stock purchases, supplier, batch and expiry details.","purchase","Add purchase")+(rows.length?'<div class="table-panel">'+table(["DATE","SUPPLIER","PRODUCT","BATCH","EXPIRY","QUANTITY","COST / UNIT","TOTAL COST"],rows.map(p=>[fmtDate(p.date),escapeHTML(p.supplierName||"Unassigned"),escapeHTML(p.productName),escapeHTML(p.batchNo||"—"),fmtDate(p.expiryDate),p.qty+" "+escapeHTML(p.unit||""),money(p.cost),money(p.total)]))+'</div>':'<div class="panel empty"><b>No purchases recorded</b>Record a purchase to add stock to your business.</div>');}
function expensesPage(d){const rows=[...d.expenses].sort((a,b)=>b.createdAt-a.createdAt);return pageIntro("Business expenses","Keep track of transport, bills and other costs.","expense","Add expense")+(rows.length?'<div class="table-panel">'+table(["DATE","DETAIL","CATEGORY","AMOUNT"],rows.map(e=>[fmtDate(e.date),escapeHTML(e.note),escapeHTML(e.category),money(e.amount)]))+'</div>':'<div class="panel empty"><b>No expenses recorded</b>Record business expenses to calculate net profit.</div>');}
function reportsPage(d){const filter=(arr)=>arr.filter(x=>{const date=x.date||"";if(reportRange==="day")return date===today();if(reportRange==="week")return within(date,7);if(reportRange==="month")return date.slice(0,7)===today().slice(0,7);if(reportRange==="year")return date.slice(0,4)===today().slice(0,4);return true;});const sales=filter(d.sales),purchases=filter(d.purchases),expenses=filter(d.expenses),adjustments=filter(d.stock_adjustments),returns=filter(d.sales_returns);const revenue=sum(sales,x=>Number(x.total))-sum(returns,x=>Number(x.amount||0)),investment=sum(purchases,x=>Number(x.total)),cogs=sum(sales,costOf)-sum(returns.filter(x=>x.restocked),x=>Number(x.cost||0)),expenseTotal=sum(expenses,x=>Number(x.amount)),stockLoss=sum(adjustments.filter(x=>x.delta<0),x=>Number(x.lossValue||0)),gross=revenue-cogs,net=gross-expenseTotal-stockLoss;const options=[["day","Today"],["week","Last 7 days"],["month","This month"],["year","This year"],["all","All time"]].map(x=>'<option value="'+x[0]+'" '+(reportRange===x[0]?"selected":"")+'>'+x[1]+'</option>').join("");return pageIntro("Business reports","Choose a period to review your business performance.")+'<div class="panel"><div class="panel-head"><div><h3>Performance summary</h3><p>Investment and profit are calculated from recorded transactions.</p></div><select id="reportRange" class="filters">'+options+'</select></div><div class="report-cards"><div class="report-card"><span>Investment</span><b>'+money(investment)+'</b></div><div class="report-card"><span>Sales</span><b>'+money(revenue)+'</b></div><div class="report-card"><span>Cost of goods sold</span><b>'+money(cogs)+'</b></div><div class="report-card"><span>Gross profit</span><b class="'+(gross>=0?"positive":"negative")+'">'+money(gross)+'</b></div><div class="report-card"><span>Expenses</span><b>'+money(expenseTotal)+'</b></div><div class="report-card"><span>Stock losses</span><b>'+money(stockLoss)+'</b></div><div class="report-card"><span>Net profit</span><b class="'+(net>=0?"positive":"negative")+'">'+money(net)+'</b></div></div><div class="form-actions" style="justify-content:flex-start;margin-top:16px"><button class="button secondary small" id="exportCsv">Export CSV</button></div></div><div class="panel"><h3 style="font-size:13px">Current stock value</h3><div class="stat-value">'+money(sum(d.products,p=>Number(p.stock||0)*Number(p.cost||0)))+'</div><p class="subtext">Based on the latest weighted-average cost per product.</p></div>';}
async function getBusinessProfile(){const rows=await all("business_profile");return rows.find(x=>x.id==="profile")||{id:"profile",name:"Karobaar Manager",phone:"",email:"",address:"",logoUrl:"",invoiceFooter:"Thank you for your business."};}
async function editBusinessProfile(){const p=await getBusinessProfile();showForm("Business profile",formField("Business / shop name","name","text",p.name||"Karobaar Manager")+formField("Phone number","phone","tel",p.phone||"",false)+formField("Email (optional)","email","email",p.email||"",false)+formField("Business address","address","text",p.address||"",false)+formField("Logo image URL (optional)","logoUrl","url",p.logoUrl||"",false)+formField("Invoice footer message","invoiceFooter","text",p.invoiceFooter||"Thank you for your business.",false),async o=>{const logoUrl=o.logoUrl.trim();if(logoUrl&&!/^https:\/\//i.test(logoUrl))throw new Error("Logo URL must start with https://");await put("business_profile",{id:"profile",name:o.name.trim()||"Karobaar Manager",phone:o.phone.trim(),email:o.email.trim(),address:o.address.trim(),logoUrl,invoiceFooter:o.invoiceFooter.trim()});toast("Business profile saved");});}
function settingsPage(d){const p=d.business_profile.find(x=>x.id==="profile")||{name:"Karobaar Manager",phone:"",address:""};return pageIntro("Backup & settings","Manage your business identity and protect your records.")+'<div class="panel"><div class="panel-head"><div><h3>Business profile</h3><p>These details appear on printed sales invoices.</p></div><button class="button" data-action="business-profile">Edit profile</button></div><div class="business-profile-summary"><b>'+escapeHTML(p.name||"Karobaar Manager")+'</b><span>'+escapeHTML(p.phone||"Phone not added")+'</span><span>'+escapeHTML(p.address||"Address not added")+'</span></div></div><div class="panel"><h3>Protect your business data</h3><p class="subtext">Download a backup file regularly. It includes products, stock adjustments, sales returns, suppliers, supplier payments, business profile, inventory batches, purchases, sales, customers, expenses and payments.</p><div class="form-actions" style="justify-content:flex-start"><button class="button" id="backupData">Download backup</button><button class="button secondary" id="chooseRestore">Restore backup</button><input id="restoreFile" type="file" accept="application/json,.json" hidden></div><p class="form-help">Restoring replaces all records currently stored on this device. Save a backup first.</p></div><div class="panel"><h3>Offline data</h3><p class="subtext">Your records stay in this browser on this device. Clearing app storage or uninstalling the app can erase them.</p></div>';}
async function downloadBackup(){const d=await data();const payload={app:"Karobaar Manager",formatVersion:1,exportedAt:new Date().toISOString(),data:d};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download="karobaar-backup-"+today()+".json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Backup downloaded");}
async function restoreBackup(file){if(!file)return;let payload;try{payload=JSON.parse(await file.text());}catch{throw new Error("Invalid backup file");}const optional=["stock_adjustments","sales_returns","suppliers","supplier_payments","business_profile","inventory_batches"];if(!payload||payload.app!=="Karobaar Manager"||!payload.data||typeof payload.data!=="object"||Array.isArray(payload.data)||!STORE_NAMES.every(n=>Array.isArray(payload.data[n])||(optional.includes(n)&&payload.data[n]===undefined)))throw new Error("This is not a valid Karobaar backup");for(const n of STORE_NAMES){const seen=new Set();for(const row of (payload.data[n]||[])){if(!row||typeof row!=="object"||Array.isArray(row)||typeof row.id!=="string"||!row.id.trim())throw new Error("Backup contains an invalid "+n+" record");if(seen.has(row.id))throw new Error("Backup contains duplicate IDs in "+n+". Nothing has been changed.");seen.add(row.id);}}if(!confirm("Restore this backup? Current records on this device will be replaced."))return;await new Promise((resolve,reject)=>{const tx=db.transaction(STORE_NAMES,"readwrite");for(const n of STORE_NAMES){const st=tx.objectStore(n);st.clear();for(const row of (payload.data[n]||[]))st.put(row);}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error("Backup restore failed"));tx.onabort=()=>reject(tx.error||new Error("Restore cancelled"));});toast("Backup restored");await render();}
function escapeHTML(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function formField(label,name,type="text",value="",required=true,extra=""){return `<div class="field"><label for="f_${name}">${label}</label><input id="f_${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" ${required?"required":""} ${extra}></div>`;}

let barcodeStream=null,barcodeLoop=0;
function stopBarcodeScanner(){if(barcodeLoop)clearTimeout(barcodeLoop);barcodeLoop=0;if(barcodeStream){barcodeStream.getTracks().forEach(t=>t.stop());barcodeStream=null;}const v=$("#barcodeVideo");if(v)v.srcObject=null;}
function selectScannedProduct(code){const key=String(code||"").trim().toLowerCase();const product=(window.__karobaarProducts||[]).find(p=>String(p.barcode||"").trim().toLowerCase()===key);if(!product){toast("No product found for barcode: "+code);return false;}const select=$("#saleProductSelect");if(!select||![...select.options].some(o=>o.value===product.id)){toast("This product is out of stock");return false;}select.value=product.id;select.dispatchEvent(new Event("change",{bubbles:true}));const input=$("#saleBarcodeInput");if(input)input.value=code;$("#f_qty")?.focus();stopBarcodeScanner();if($("#barcodeScannerPanel"))$("#barcodeScannerPanel").hidden=true;toast("Product found: "+product.name);return true;}
async function startBarcodeScanner(){if(!("BarcodeDetector" in window)){toast("Camera scanning is unsupported here. Use barcode input or a Bluetooth scanner.");return;}if(!navigator.mediaDevices?.getUserMedia){toast("Camera requires HTTPS and browser permission.");return;}stopBarcodeScanner();const panel=$("#barcodeScannerPanel"),video=$("#barcodeVideo");if(!panel||!video)return;panel.hidden=false;try{barcodeStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});video.srcObject=barcodeStream;await video.play();const detector=new BarcodeDetector({formats:["qr_code","ean_13","ean_8","upc_a","upc_e","code_128","code_39","itf","codabar"]});const scan=async()=>{if(!barcodeStream||panel.hidden)return;try{const codes=await detector.detect(video);if(codes.length&&selectScannedProduct(codes[0].rawValue))return;}catch(e){}barcodeLoop=setTimeout(scan,220);};scan();}catch(e){stopBarcodeScanner();panel.hidden=true;toast("Camera could not start. Check camera permission.");}}
function showForm(title,fields,submit,help=""){modal(title,`<form id="entryForm"><div class="form-grid">${fields}</div>${help?`<p class="form-help">${help}</p>`:""}<div class="form-actions"><button type="button" class="button secondary" id="cancelForm">Cancel</button><button class="button" type="submit">Save record</button></div></form>`);$("#cancelForm").onclick=closeModal;$("#entryForm").onsubmit=async e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.target));try{await submit(obj);closeModal();await render();}catch(err){toast(err.message||"Could not save record");}};}
async function editProduct(id){const d=await data(),p=d.products.find(x=>x.id===id);if(!p)return;showForm("Edit product",formField("Product name","name","text",p.name)+formField("Unit","unit","text",p.unit||"unit")+formField("Barcode / QR value (optional)","barcode","text",p.barcode||"",false)+formField("Minimum stock alert quantity","minStock","number",p.minStock??0,true,'min="0" step="any"')+formField("Purchase cost per unit (Rs.)","cost","number",p.cost,true,'min="0" step="0.01"')+formField("Default selling rate (Rs.)","price","number",p.price,true,'min="0" step="0.01"'),async o=>{const latest=(await data()).products.find(x=>x.id===id);if(!latest)throw new Error("Product no longer exists");const barcode=o.barcode.trim();if(barcode&&(await data()).products.some(x=>x.id!==id&&String(x.barcode||"").toLowerCase()===barcode.toLowerCase()))throw new Error("Barcode already assigned");const minStock=Number(o.minStock);if(!Number.isFinite(minStock)||minStock<0)throw new Error("Enter a valid minimum stock level");latest.name=o.name.trim();latest.unit=o.unit.trim()||"unit";latest.barcode=barcode;latest.minStock=minStock;latest.cost=Number(o.cost);latest.price=Number(o.price);await put("products",latest);toast("Product updated");});}
async function deleteProduct(id){const d=await data(),p=d.products.find(x=>x.id===id);if(!p)return;if(d.sales.some(x=>x.productId===id)||d.purchases.some(x=>x.productId===id)){toast("This product has transaction history and cannot be deleted. Edit its details instead.");return;}if(Number(p.stock||0)!==0){toast("Product has stock remaining. Adjust stock to zero before deleting.");return;}if(!confirm('Delete "'+p.name+'"? This cannot be undone.'))return;await remove("products",id);toast("Product deleted");await render();}
async function addStockAdjustment(){const d=await data();if(!d.products.length){toast("Add a product first");return;}const options=d.products.map(p=>'<option value="'+p.id+'">'+escapeHTML(p.name)+' — available '+Number(p.stock||0)+' '+escapeHTML(p.unit||"")+'</option>').join("");showForm("Adjust stock",'<div class="field full"><label>Product</label><select name="productId">'+options+'</select></div><div class="field"><label>Adjustment type</label><select name="direction"><option value="remove">Reduce stock</option><option value="add">Increase stock</option></select></div>'+formField("Quantity","qty","number","",true,'min="0.001" step="any"')+'<div class="field full"><label>Reason</label><select name="reason"><option>Damaged goods</option><option>Missing / lost stock</option><option>Physical stock count correction</option><option>Found extra stock</option><option>Other</option></select></div>'+formField("Date","date","date",today()),async o=>{const fresh=await data(),p=fresh.products.find(x=>x.id===o.productId);if(!p)throw new Error("Product not found");const qty=Number(o.qty);if(!Number.isFinite(qty)||qty<=0)throw new Error("Enter a valid quantity");const direction=o.direction==="add"?1:-1;if(direction<0&&qty>Number(p.stock||0))throw new Error("Cannot reduce more than available stock");const delta=direction*qty,lossValue=direction<0?qty*Number(p.cost||0):0;p.stock=Number(p.stock||0)+delta;const batches=fresh.inventory_batches.filter(x=>x.productId===p.id&&Number(x.remaining||0)>0).sort((a,b)=>(a.expiryDate||"9999").localeCompare(b.expiryDate||"9999"));const changed=[];if(direction<0){let left=qty;for(const batch of batches){if(left<=0)break;const take=Math.min(left,Number(batch.remaining));batch.remaining-=take;changed.push(batch);left-=take;}}else{changed.push({id:uid(),productId:p.id,productName:p.name,batchNo:"Stock adjustment",expiryDate:"",qty,remaining:qty,date:o.date,createdAt:Date.now()});}await new Promise((resolve,reject)=>{const tx=db.transaction(["products","stock_adjustments","inventory_batches"],"readwrite");tx.objectStore("products").put(p);tx.objectStore("stock_adjustments").put({id:uid(),productId:p.id,productName:p.name,unit:p.unit,delta,reason:o.reason,date:o.date,lossValue,createdAt:Date.now()});for(const batch of changed)tx.objectStore("inventory_batches").put(batch);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Stock adjustment failed"));});toast("Stock adjusted successfully");});}
async function addSupplier(){showForm("Add supplier",formField("Supplier / business name","name")+formField("Phone number (optional)","phone","tel","",false)+formField("Address (optional)","address","text","",false),async o=>{const name=o.name.trim();if(!name)throw new Error("Enter supplier name");await put("suppliers",{id:uid(),name,phone:o.phone.trim(),address:o.address.trim(),createdAt:Date.now()});toast("Supplier saved");});}
async function addSupplierPayment(supplierId){const d=await data(),s=d.suppliers.find(x=>x.id===supplierId);if(!s){toast("Supplier not found");return;}const balance=supplierBalance(d,s).balance;if(balance<=0){toast("No outstanding supplier balance");return;}showForm("Record supplier payment",'<div class="field full"><label>Supplier</label><input value="'+escapeHTML(s.name)+'" disabled></div>'+formField("Amount paid (Rs.)","amount","number","",true,'min="0.01" max="'+balance+'" step="0.01"')+formField("Payment date","date","date",today())+formField("Note (optional)","note","text","",false),async o=>{const amount=Number(o.amount),fresh=await data(),latest=fresh.suppliers.find(x=>x.id===supplierId),latestBalance=latest?supplierBalance(fresh,latest).balance:0;if(amount<=0||amount>latestBalance)throw new Error("Enter an amount up to "+money(latestBalance));await put("supplier_payments",{id:uid(),supplierId:s.id,supplierName:s.name,amount,date:o.date,note:o.note.trim(),createdAt:Date.now()});toast("Supplier payment recorded");});}
async function addProduct(){showForm("Add new product",formField("Product name","name")+formField("Unit (e.g. kg, piece, litre)","unit","text","kg")+formField("Barcode / QR value (optional)","barcode","text","",false)+formField("Minimum stock alert quantity","minStock","number","0",true,'min="0" step="any"')+formField("Purchase cost per unit (Rs.)","cost","number","",true,'min="0" step="0.01"')+formField("Default selling rate (Rs.)","price","number","",true,'min="0" step="0.01"'),async o=>{const barcode=o.barcode.trim();if(barcode&&(await data()).products.some(p=>String(p.barcode||"").toLowerCase()===barcode.toLowerCase()))throw new Error("Barcode already assigned");const minStock=Number(o.minStock);if(!Number.isFinite(minStock)||minStock<0)throw new Error("Enter a valid minimum stock level");await put("products",{id:uid(),name:o.name.trim(),unit:o.unit.trim()||"unit",barcode,minStock,cost:+o.cost,price:+o.price,stock:0,createdAt:Date.now()});toast("Product added successfully");});}
async function addCustomer(){showForm("Add customer",formField("Customer name","name")+formField("Phone number (optional)","phone","tel","",false),async o=>{await put("customers",{id:uid(),name:o.name.trim(),phone:o.phone.trim(),createdAt:Date.now()});toast("Customer saved");});}
async function addPurchase(){const d=await data();if(!d.products.length){toast("Please add a product first");return;}const opts=d.products.map(p=>`<option value="${p.id}">${escapeHTML(p.name)} — ${escapeHTML(p.unit)}</option>`).join("");const supplierOptions=d.suppliers.map(s=>'<option value="'+s.id+'">'+escapeHTML(s.name)+'</option>').join("");showForm("Add stock purchase",'<div class="field full"><label>Supplier (optional)</label><select name="supplierId"><option value="">Not assigned</option>'+supplierOptions+'</select></div>'+ `<div class="field full"><label>Choose product</label><select name="productId" id="f_productId">${opts}</select></div>`+formField("Quantity purchased","qty","number","",true,'min="0.001" step="any"')+formField("Cost per unit (Rs.)","cost","number","",true,'min="0" step="0.01"')+formField("Batch / lot number","batchNo","text","",false)+formField("Expiry date (optional)","expiryDate","date","",false)+formField("Purchase date","date","date",today()),async o=>{const fresh=await data(),p=fresh.products.find(x=>x.id===o.productId),supplier=fresh.suppliers.find(x=>x.id===o.supplierId),qty=Number(o.qty),cost=Number(o.cost);if(!p)throw new Error("Product not found");if(!Number.isFinite(qty)||qty<=0||!Number.isFinite(cost)||cost<0)throw new Error("Enter valid purchase quantity and cost");const total=qty*cost,oldStock=Number(p.stock||0),newStock=oldStock+qty;p.cost=newStock>0?((oldStock*Number(p.cost||0))+(qty*cost))/newStock:cost;p.stock=newStock;const purchase={id:uid(),productId:p.id,productName:p.name,unit:p.unit,qty,cost,total,supplierId:supplier?.id||"",supplierName:supplier?.name||"",batchNo:o.batchNo.trim(),expiryDate:o.expiryDate||"",date:o.date,createdAt:Date.now()};await new Promise((resolve,reject)=>{const batch={id:uid(),productId:p.id,productName:p.name,batchNo:o.batchNo.trim(),expiryDate:o.expiryDate||"",qty,remaining:qty,purchaseId:purchase.id,date:o.date,createdAt:Date.now()};const tx=db.transaction(["products","purchases","inventory_batches"],"readwrite");tx.objectStore("products").put(p);tx.objectStore("purchases").put(purchase);tx.objectStore("inventory_batches").put(batch);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Could not save purchase"));});toast("Stock added successfully");});}
async function addSale(){
 const d=await data();
 if(!d.products.some(p=>Number(p.stock||0)>0)){toast("Add products and stock before recording a sale");return;}
 const customers=d.customers,products=d.products.filter(p=>Number(p.stock||0)>0);
 window.__karobaarProducts=d.products;
 const productOptions=products.map(p=>'<option value="'+p.id+'">'+escapeHTML(p.name)+' (Stock: '+p.stock+' '+escapeHTML(p.unit||'')+')</option>').join("");
 const fields='<div class="field full"><label>Customer</label><select name="customerId"><option value="">Walk-in customer</option>'+customers.map(c=>'<option value="'+c.id+'">'+escapeHTML(c.name)+'</option>').join("")+'</select></div>'+
 '<div class="field full"><label>Product to add</label><select name="productId" id="saleProductSelect">'+productOptions+'</select></div>'+
 '<div class="field full"><label>Scan barcode / QR or enter code</label><div class="pos-scan-row"><input id="saleBarcodeInput" type="text" placeholder="Scan or type barcode"><button type="button" class="button secondary" id="startBarcodeScan">Scan with camera</button></div><div id="barcodeScannerPanel" class="barcode-scanner" hidden><video id="barcodeVideo" playsinline muted></video><button type="button" class="button secondary small" id="stopBarcodeScan">Stop camera</button></div></div>'+
 formField("Quantity","qty","number","1",true,'min="0.001" step="any"')+
 formField("Selling rate per unit (Rs.)","rate","number",products[0].price,true,'min="0" step="0.01"')+
 '<div class="field full"><button type="button" class="button secondary" id="addCartItem">＋ Add product to invoice</button></div>'+
 '<div class="field full"><div class="pos-cart"><b>Invoice items</b><div id="posCartItems" class="pos-cart-items"><p class="muted">No products added yet.</p></div><div class="pos-cart-total"><span>Subtotal</span><b id="posSubtotal">Rs. 0</b></div></div></div>'+
 formField("Invoice discount (Rs.)","discount","number","0",true,'min="0" step="0.01"')+
 formField("Sale date","date","date",today())+
 formField("Amount received (Rs.)","paid","number","0",true,'min="0" step="0.01"');
 modal("Quick POS sale",'<form id="entryForm"><div class="form-grid">'+fields+'</div><div class="form-actions"><button type="button" class="button secondary" id="cancelForm">Cancel</button><button class="button" type="submit">Save invoice</button></div></form>');
 const cart=[];
 const refreshCart=()=>{
  const host=$("#posCartItems"),subtotal=cart.reduce((t,x)=>t+x.qty*x.rate,0);
  host.innerHTML=cart.length?cart.map((x,i)=>'<div class="pos-cart-row"><span><b>'+escapeHTML(x.name)+'</b><small>'+x.qty+' '+escapeHTML(x.unit)+' × '+money(x.rate)+'</small></span><b>'+money(x.qty*x.rate)+'</b><button type="button" class="button danger small" data-cart-remove="'+i+'">Remove</button></div>').join(""):'<p class="muted">No products added yet.</p>';
  $("#posSubtotal").textContent=money(subtotal);
 };
 $("#posCartItems").addEventListener("click",e=>{const b=e.target.closest("[data-cart-remove]");if(!b)return;cart.splice(Number(b.dataset.cartRemove),1);refreshCart();});
 $("#addCartItem").onclick=()=>{
  const p=products.find(x=>x.id===$("#saleProductSelect").value),qty=Number($("#f_qty").value),rate=Number($("#f_rate").value);
  if(!p||!Number.isFinite(qty)||qty<=0||!Number.isFinite(rate)||rate<0){toast("Select a product and enter valid quantity and rate");return;}
  const existing=cart.find(x=>x.productId===p.id);
  const nextQty=qty+(existing?.qty||0);
  if(nextQty>Number(p.stock||0)){toast("Not enough stock for "+p.name);return;}
  if(existing){existing.qty=nextQty;existing.rate=rate;}else cart.push({productId:p.id,name:p.name,unit:p.unit||"unit",qty,rate});
  refreshCart();$("#f_qty").value="1";
 };
 $("#saleProductSelect").onchange=e=>{const p=products.find(x=>x.id===e.target.value);if(p)$("#f_rate").value=p.price;};
 $("#startBarcodeScan").onclick=startBarcodeScanner;
 $("#stopBarcodeScan").onclick=()=>{stopBarcodeScanner();$("#barcodeScannerPanel").hidden=true;};
 $("#saleBarcodeInput").addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();selectScannedProduct(e.target.value);}});
 $("#cancelForm").onclick=closeModal;
 $("#entryForm").onsubmit=async e=>{
  e.preventDefault();
  try{
   if(!cart.length)throw new Error("Add at least one product to the invoice");
   const o=Object.fromEntries(new FormData(e.target)),fresh=await data();
   const subtotal=cart.reduce((t,x)=>t+x.qty*x.rate,0),discount=Number(o.discount||0),paid=Number(o.paid||0);
   if(!Number.isFinite(discount)||discount<0||discount>subtotal)throw new Error("Discount must be between zero and the subtotal");
   const grandTotal=subtotal-discount;
   if(!Number.isFinite(paid)||paid<0||paid>grandTotal)throw new Error("Amount received cannot exceed invoice total");
   const customer=fresh.customers.find(c=>c.id===o.customerId),saleId=uid(),invoiceNo="INV-"+o.date.replace(/-/g,"")+"-"+saleId.slice(-5).toUpperCase();
   const productUpdates=[],batchUpdates=[],records=[];
   for(const line of cart){
    const p=fresh.products.find(x=>x.id===line.productId);
    if(!p||Number(p.stock||0)<line.qty)throw new Error("Stock changed for "+line.name+". Reopen the invoice.");
    const gross=line.qty*line.rate,share=subtotal?discount*gross/subtotal:0,net=Math.max(0,gross-share),cost=line.qty*Number(p.cost||0);
    const allocations=batchAllocations(fresh,p.id,line.qty);p.stock=Number(p.stock||0)-line.qty;productUpdates.push(p);
    for(const a of allocations){const b=fresh.inventory_batches.find(x=>x.id===a.batchId);if(b)batchUpdates.push(b);}
    records.push({id:uid(),invoiceNo,productId:p.id,productName:p.name,unit:p.unit,customerId:customer?.id||"",customerName:customer?.name||"Walk-in customer",qty:line.qty,rate:net/line.qty,grossRate:line.rate,grossTotal:gross,discountShare:share,total:net,cost,profit:net-cost,paid:grandTotal?paid*net/grandTotal:0,batchAllocations:allocations,date:o.date,createdAt:Date.now()});
   }
   await new Promise((resolve,reject)=>{const tx=db.transaction(["products","sales","inventory_batches"],"readwrite");for(const p of productUpdates)tx.objectStore("products").put(p);for(const b of batchUpdates)tx.objectStore("inventory_batches").put(b);for(const row of records)tx.objectStore("sales").put(row);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Could not save invoice"));});
   const rateChanges=records.filter((row,i)=>row.grossRate!==Number(productUpdates.find(p=>p.id===row.productId)?.price));
   if(rateChanges.length&&confirm("Update the saved default selling rate for the product(s) whose rate you changed?")){for(const row of rateChanges){const p=productUpdates.find(x=>x.id===row.productId);if(p){p.price=row.grossRate;await put("products",p);}}}
   toast("Invoice saved with "+records.length+" item(s)");
   closeModal();await render();
  }catch(err){toast(err.message||"Could not save invoice");}
 };
}

async function addPayment(customerId){const d=await data();const c=d.customers.find(x=>x.id===customerId);if(!c){toast("Customer not found");return;}const balance=customerBalance(d,c).balance;if(balance<=0){toast("No outstanding balance");return;}showForm("Receive customer payment",'<div class="field full"><label>Customer</label><input value="'+escapeHTML(c.name)+'" disabled></div>'+formField("Amount received (Rs.)","amount","number","",true,'min="0.01" max="'+balance+'" step="0.01"')+formField("Payment date","date","date",today())+formField("Note (optional)","note","text","",false),async o=>{const amount=Number(o.amount),fresh=await data(),latest=fresh.customers.find(x=>x.id===customerId),latestBalance=latest?customerBalance(fresh,latest).balance:0;if(!Number.isFinite(amount)||amount<=0||amount>latestBalance)throw new Error("Outstanding balance changed. Enter an amount up to "+money(latestBalance));await put("payments",{id:uid(),customerId:c.id,customerName:c.name,amount,date:o.date,note:o.note.trim(),createdAt:Date.now()});toast("Payment recorded");});}
async function addExpense(){showForm("Add business expense",formField("Expense details","note")+formField("Category","category","text","General")+formField("Amount (Rs.)","amount","number","",true,'min="0.01" step="0.01"')+formField("Date","date","date",today()),async o=>{await put("expenses",{id:uid(),note:o.note.trim(),category:o.category.trim(),amount:+o.amount,date:o.date,createdAt:Date.now()});toast("Expense saved");});}
document.addEventListener("click",async e=>{const page=e.target.closest("[data-page]");if(page){currentPage=page.dataset.page;$("#sidebar").classList.remove("open");await render();return;}const actionButton=e.target.closest("[data-action]");const action=actionButton?.dataset.action;if(action){if(action==="stock-adjustment"){addStockAdjustment();return;}if(action==="return-sale"){addSaleReturn(actionButton.dataset.id);return;}if(action==="supplier-ledger"){showSupplierLedger(actionButton.dataset.supplierId);return;}if(action==="business-profile"){editBusinessProfile();return;}if(action==="product-history"){showProductHistory(actionButton.dataset.id);return;}if(action==="supplier-payment"){addSupplierPayment(actionButton.dataset.supplierId);return;}if(action==="invoice"){showSaleInvoice(actionButton.dataset.id);return;}if(action==="edit-product"){editProduct(actionButton.dataset.id);return;}if(action==="delete-product"){deleteProduct(actionButton.dataset.id);return;}const customerId=actionButton.dataset.customerId;if(action==="ledger"){showCustomerLedger(customerId);return;}if(action==="payment"){addPayment(customerId);return;}({sale:addSale,product:addProduct,purchase:addPurchase,customer:addCustomer,expense:addExpense,supplier:addSupplier}[action])?.();}});
