$("#closeModal").onclick=closeModal;$("#modal").addEventListener("click",e=>{if(e.target.id==="modal")closeModal();});$("#mobileMenu").onclick=()=>$("#sidebar").classList.toggle("open");
$("#pageContent").addEventListener("input",e=>{if(e.target.id==="productSearch"){const q=e.target.value.toLowerCase();$("#productsTable")?.querySelectorAll("tbody tr").forEach(row=>row.style.display=row.innerText.toLowerCase().includes(q)?"":"none");}});
$("#pageContent").addEventListener("change",e=>{if(e.target.id==="chartRange"){chartRange=e.target.value;render();}if(e.target.id==="reportRange"){reportRange=e.target.value;render();}});
$("#pageContent").addEventListener("click",e=>{if(e.target.id==="exportCsv")exportCSV();if(e.target.id==="backupData")downloadBackup();if(e.target.id==="chooseRestore")$("#restoreFile").click();});
$("#pageContent").addEventListener("change",async e=>{if(e.target.id==="restoreFile"){try{await restoreBackup(e.target.files[0]);}catch(err){toast(err.message||"Restore failed");}e.target.value="";}});
async function exportCSV(){const d=await data();const rows=[["Type","Date","Name","Quantity","Rate","Total","Cost","Profit"]];for(const s of d.sales)rows.push(["Sale",s.date,s.customerName,s.qty,s.rate,s.total,s.cost,s.profit]);for(const p of d.purchases)rows.push(["Purchase",p.date,p.productName,p.qty,p.cost,p.total,p.total,""]);for(const x of d.expenses)rows.push(["Expense",x.date,x.note,"","","",x.amount,""]);for(const p of d.payments)rows.push(["Customer payment",p.date,p.customerName,"","","",p.amount,""]);for(const x of d.stock_adjustments)rows.push(["Stock adjustment",x.date,x.productName,x.delta,"","",x.lossValue||0,""]);for(const x of d.sales_returns)rows.push(["Sales return",x.date,x.customerName,x.qty,x.rate,x.amount,x.cost||0,-(Number(x.amount||0)-Number(x.restocked?x.cost||0:0))]);for(const x of d.supplier_payments)rows.push(["Supplier payment",x.date,x.supplierName,"","","",x.amount,""]);const csv=rows.map(r=>r.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(",")).join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="karobaar-report.csv";a.click();URL.revokeObjectURL(a.href);}
